2260	    mbedtls_x509_crt *child,
2261	    mbedtls_x509_crt *candidates,
2262	    mbedtls_x509_crt **r_parent,
2263	    int *r_signature_is_good,
2264	    int top,
2265	    unsigned path_cnt,
2266	    unsigned self_cnt,
2267	    mbedtls_x509_crt_restart_ctx *rs_ctx,
2268	    const mbedtls_x509_time *now)
2269	{
2270	    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
2271	    mbedtls_x509_crt *parent, *fallback_parent;
2272	    int signature_is_good = 0, fallback_signature_is_good;
2273	
2274	#if defined(MBEDTLS_ECDSA_C) && defined(MBEDTLS_ECP_RESTARTABLE)
2275	    /* did we have something in progress? */
2276	    if (rs_ctx != NULL && rs_ctx->parent != NULL) {
2277	        /* restore saved state */
2278	        parent = rs_ctx->parent;
2279	        fallback_parent = rs_ctx->fallback_parent;
2280	        fallback_signature_is_good = rs_ctx->fallback_signature_is_good;
2281	
2282	        /* clear saved state */
2283	        rs_ctx->parent = NULL;
2284	        rs_ctx->fallback_parent = NULL;
2285	        rs_ctx->fallback_signature_is_good = 0;
2286	
2287	        /* resume where we left */
2288	        goto check_signature;
2289	    }
2290	#endif
2291	
2292	    fallback_parent = NULL;
2293	    fallback_signature_is_good = 0;
2294	
2295	    for (parent = candidates; parent != NULL; parent = parent->next) {
2296	        /* basic parenting skills (name, CA bit, key usage) */
2297	        if (x509_crt_check_parent(child, parent, top) != 0) {
2298	            continue;
2299	        }
2300	
2301	        /* +1 because stored max_pathlen is 1 higher that the actual value */
2302	        if (parent->max_pathlen > 0 &&
2303	            (size_t) parent->max_pathlen < 1 + path_cnt - self_cnt) {
2304	            continue;
2305	        }
2306	
2307	        /* Signature */
2308	#if defined(MBEDTLS_ECDSA_C) && defined(MBEDTLS_ECP_RESTARTABLE)
2309	check_signature:
2310	#endif
2311	        ret = x509_crt_check_signature(child, parent, rs_ctx);
2312	
2313	#if defined(MBEDTLS_ECDSA_C) && defined(MBEDTLS_ECP_RESTARTABLE)
2314	        if (rs_ctx != NULL && ret == MBEDTLS_ERR_ECP_IN_PROGRESS) {
2315	            /* save state */
2316	            rs_ctx->parent = parent;
2317	            rs_ctx->fallback_parent = fallback_parent;
2318	            rs_ctx->fallback_signature_is_good = fallback_signature_is_good;
2319	
2320	            return ret;
2321	        }
2322	#else
2323	        (void) ret;
2324	#endif
2325	
2326	        signature_is_good = ret == 0;
2327	        if (top && !signature_is_good) {
2328	            continue;
2329	        }
2330	
2331	#if defined(MBEDTLS_HAVE_TIME_DATE)
2332	        /* optional time check */
2333	        if (mbedtls_x509_time_cmp(&parent->valid_to, now) < 0 ||    /* past */
2334	            mbedtls_x509_time_cmp(&parent->valid_from, now) > 0) {  /* future */
2335	            if (fallback_parent == NULL) {
2336	                fallback_parent = parent;
2337	                fallback_signature_is_good = signature_is_good;
2338	            }
2339	
2340	            continue;
2341	        }
2342	#else
2343	        ((void) now);
2344	#endif
